syntax:
// sequence: print one term per round
for (int i = 1; i <= n; i++) {
    cout << 2 * i << " ";      // term as a formula of i
}

// series: keep a running total
int sum = 0;                    // sum starts at 0
for (int i = 1; i <= n; i++) {
    sum = sum + i;              // add the i-th term
}
cout << sum;                    // print after the loop

int fact = 1;                   // a product starts at 1
for (int i = 1; i <= n; i++) {
    fact = fact * i;
}

// fraction series: use double and 1.0
double h = 0;
for (int i = 1; i <= n; i++) {
    h = h + 1.0 / i;
}
cout << fixed << setprecision(3) << h;   // needs <iomanip>

sample.code:
#include <iostream>
using namespace std;

int main() {
    const int n = 5;

    cout << "Even: ";
    for (int i = 1; i <= n; i++) {
        cout << 2 * i << " ";
    }
    cout << endl;

    cout << "Powers of 2: ";
    int p = 1;
    for (int i = 1; i <= n; i++) {
        p = p * 2;
        cout << p << " ";
    }
    cout << endl;

    int sum = 0;
    int fact = 1;
    for (int i = 1; i <= n; i++) {
        sum = sum + i;
        fact = fact * i;
    }
    cout << "Sum = " << sum << endl;
    cout << "Factorial = " << fact << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int n;
    cin >> n;
    double sum = 0;
    for (int i = 1; i <= n; i++) {
        double term = 1.0 / i;
        sum = sum + term;
    }
    cout << fixed << setprecision(3);
    cout << "Sum = " << sum << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int a = 0, b = 1;
    int sum = 0;
    cout << "Fibonacci: ";
    for (int i = 1; i <= n; i++) {
        cout << a << " ";
        sum = sum + a;
        int next = a + b;
        a = b;
        b = next;
    }
    cout << endl;
    cout << "Sum = " << sum << endl;
    return 0;
}

